 * callstack` — the row is referenced from `cont`'s continuation type, and
 * going through the instance would make that reference eagerly circular.
 */
export type Evaluation<A> = Eff.Eff<Actions | Eff.Only<typeof Metas.registry, "Registry.get"> | Eff.Actions<typeof M.reader> | Eff.Actions<typeof evalMode>, A>;

